"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2577],{2577:a=>{a.exports=JSON.parse('{"slug":"semeynaya-ipoteka-oktyabr-2026-stavki","locale":"zh","title":"一个孩子家庭的优惠房贷从6%升至10–12%","description":"2026年十月1日起家庭房贷按子女人数和地区，利率2%至12%。分析月供变化及不受影响者。","blocks":[{"id":"b001","kind":"paragraph","text":"2026年十月1日起，家庭房贷按孩子数量定价，此前统一6%。如今一个孩子家庭在地方10%，莫斯科、圣彼得堡及两地周边12%。每增加一个孩子降2个百分点，五个孩子时地方2%、两大城市4%。"},{"id":"b002","kind":"paragraph","text":"十月1日起贷款上限也按人数：地方一个孩子6百万卢布、两个8百万、三个及以上10百万；莫斯科、圣彼得堡及周边分别12、15、18百万。至少一名孩子未满7岁。首付仍从20%起，可用生育资本支付。"},{"id":"b003","kind":"paragraph","text":"两种情况不论孩子多少都保留不高于6%：孩子残疾，或家庭自有资金付至少一半房价，或交易后一年内将债务降至50%。新条件只针对2026年十月1日起合同，此前借款不受影响。"},{"id":"b004","kind":"paragraph","text":"优惠机制是银行低息放贷，国家补足与市场利率差额，称利率补贴。央行关键利率目前14%，越高则每笔优惠贷款财政补贴越多。新规则只补最初15年，过去覆盖全部期限；15年后可能升至市场利率。"},{"id":"b005","kind":"paragraph","text":"卢布差额明显：6百万卢布、30年、6%月供约36千；同笔按10%，地方一个孩子家庭前15年月供约52.7千，多16.7千。地方三个孩子仍6%，莫斯科圣彼得堡升至8%。优惠仍大：2026年九月24日大银行普通房贷全成本约22%年化。"},{"id":"b006","kind":"paragraph","text":"尚未知新规则对新房需求与价格的影响。一个孩子家庭以10–12%借款，指望很快再融资，就是押注无人承诺的央行降息，下一决定十月23日。推迟也需继续付租金。首付半价可恢复6%，却可能耗尽安全垫。"},{"id":"b007","kind":"heading","text":"2026年十月1日起家庭房贷利率如何？"},{"id":"b008","kind":"paragraph","text":"地方一个孩子10%，两个8%，三个6%，四个4%，五个及以上2%；莫斯科、圣彼得堡及周边高2个百分点，即12%到4%。"},{"id":"b009","kind":"heading","text":"已办家庭房贷会改利率吗？"},{"id":"b010","kind":"paragraph","text":"不会。新条件仅适用2026年十月1日起签约，旧贷款仍6%。"},{"id":"b011","kind":"heading","text":"一个孩子也能拿6%吗？"},{"id":"b012","kind":"paragraph","text":"两种情况可以：孩子残疾，或家庭自付至少一半房价，或一年内把贷款余额降至50%。"}],"sources":[{"label":"家庭房贷与子女人数挂钩","url":"https://lenta.ru/news/2026/10/01/long-sem-ipo"},{"label":"2026年十月1日起家庭房贷新利率、上限和条件","url":"https://finance.mail.ru/article/semejnaya-ipoteka-po-novym-usloviyam-chto-menyaetsya-s-1-oktyabrya-69230142/"},{"label":"2026年十月1日起家庭房贷完整新条件","url":"https://bankinform.ru/news/143196"},{"label":"家庭房贷条件将于2026年十月1日变化","url":"https://rb.ru/news/usloviya-po-semejnoj-ipoteke-izmenyatsya-s-1-oktyabrya-2026-goda-stavka-budet-privyazana-k-kolichestvu-detej/"},{"label":"2026年十月1日起按子女人数的利率与上限","url":"https://finuslugi.ru/navigator/kak-ehto-rabotaet/stat_semeynaya-ipoteka-menyaetsya-s-1-iyulya"},{"label":"2026年九月房贷成本停滞","url":"https://brobank.ru/stoimost-ipoteki-sentyabr-2026-goda/"},{"label":"俄罗斯央行维持关键利率14%","url":"https://www.cbr.ru/press/keypr/"}],"sourceBodySha256":"910527a74fa7b29390aaa229e3ba15e4be6028a23c1921d265fdaa19884579bc"}')}}]);